export function expiringSoon(wallet: Wallet, day: number, within: number): number {
  if (within <= 0) return 0;
  let total = 0;
  for (const batch of wallet.batches) {
    const lastGoodDay = batch.bought + TOKEN_LIFE_DAYS - 1;
    const liveNow = batch.bought <= day && day <= lastGoodDay;
    const deadLater = day + within > lastGoodDay;
    if (liveNow && deadLater) total += batch.left;
  }
  return total;
}
